import { SheetBody } from '../../slots/defs/sheetBody';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import { liveHolds, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { useClaims } from '../claims/claims';
import { trimmedSumDue, useRates } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';
import { useFloor, useLate } from '../access/access';
import { personOverdue } from './overdue';
import { Col } from '../columns/columns';

function OverdueHead() {
  return (
    <>
      <Col name="overdue-count"><th>Overdue</th></Col>
      <Col name="overdue-total"><th>Overdue due</th></Col>
    </>
  );
}

// A person's overdue claims that count: how many, and their due added up.
function PersonOverdue({ sheetId, person }: { sheetId: string; person: Person }) {
  const claims = (useClaims(sheetId).data ?? []).filter((c) => c.personId === person.id);
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const { count, total } = personOverdue(rates, person.grades, today, claims, liveHolds(person, today), floor, late);
  return (
    <>
      <Col name="overdue-count"><td data-testid="person-overdue-count">{count}</td></Col>
      <Col name="overdue-total"><td data-testid="person-overdue-total">{total}</td></Col>
    </>
  );
}

// The sheet's overdue claims that count: everyone's overdue count and overdue-total added up
// (the overdue-total trimmed of the highest and lowest person's).
function OverdueTotal({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const each = people.map((p) =>
    personOverdue(rates, p.grades, today, claims.filter((c) => c.personId === p.id), liveHolds(p, today), floor, late),
  );
  return (
    <p>
      Overdue: <strong data-testid="rollup-overdue-count">{each.reduce((n, o) => n + o.count, 0)}</strong>, due{' '}
      <strong data-testid="rollup-overdue-total">{trimmedSumDue(each.map((o) => o.total))}</strong>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: 25, Component: OverdueTotal }),
  PersonHead.fill({ order: 25, Component: OverdueHead }),
  PersonRow.fill({ order: 25, Component: PersonOverdue }),
];
import { gradeOn } from '../people/people';
import type { GradeFrom, Hold } from '../people/people';
import { counts, isDeferred, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, overdueFrom, rateOn, sumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';

/** A claim's due-by: fixed when it was made, the terms-th business day after its date, from its person's own terms, else its grade's terms then. */
export const dueBy = (claim: Claim): string => claim.dueBy;

/**
 * Whether a claim is overdue: open (OPEN or PENDING), not deferred, and its due-by plus the grace of
 * its `grade` (the one in force on its date) before the sheet's `today`.
 */
export const isOverdue = (claim: Claim, today: string, late: Late, grade: string): boolean =>
  isOpen(claim) && !isDeferred(claim, today) && today !== '' && overdueFrom(claim, grade, late) < today;

/**
 * A person's overdue claims that count (not an unbound OPEN one dated within one of their `holds`, as it then counts in
 * no total): how many, and their due figures (with their late charge) added up, skipping n/a.
 */
export function personOverdue(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
): { count: number; total: string } {
  const overdue = claims.filter((c) => counts(c, holds, today) && isOverdue(c, today, late, gradeOn(grades, c.date)));
  return {
    count: overdue.length,
    total: sumDue(overdue.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date, c.id), floor, late, gradeOn(grades, c.date)))),
  };
}
import type { ReactNode } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useUser } from '../session/session';

// The people-list columns a user can switch off on their own screen. Each is kept per user, not
// per sheet; a column switched off has no cell (and no header cell) at all, and every figure is
// worked out as before.
export const COLUMNS = [
  'claimed',
  'due-total',
  'excess',
  'statement-count',
  'stated-total',
  'statement-date',
  'overdue-count',
  'overdue-total',
  'patrons',
  'backing',
  'hold',
  'retired',
  'terms',
  'contact',
  'aliases',
] as const;
export type ColumnKey = (typeof COLUMNS)[number];

export const columnsKey = (user: string) => ['user', user, 'columns'] as const;

/** The columns the signed-in user has switched off: none until they switch one off. */
export function useHiddenColumns(user: string) {
  return useQuery({
    queryKey: columnsKey(user),
    queryFn: async () => (await getJson<{ hidden: string[] }>('/api/columns', user)).hidden,
  });
}

/** Renders a people-list cell (or its header cell) only while the signed-in user shows `name`. */
export function Col({ name, children }: { name: ColumnKey; children: ReactNode }) {
  const [user] = useUser();
  const hidden = useHiddenColumns(user);
  return hidden.data?.includes(name) ? null : <>{children}</>;
}
package net.officefloor.hq.app.columns;

import java.util.Set;
import net.officefloor.hq.app.setting.InvalidSettingException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateColumn {

    /** The people-list columns a user may switch off. */
    static final Set<String> COLUMNS = Set.of("claimed", "due-total", "excess", "statement-count", "stated-total",
            "statement-date", "overdue-count", "overdue-total", "patrons", "backing", "hold", "retired", "terms",
            "contact", "aliases");

    public void validate(@RequestBody ColumnRequest request, Out<ColumnInput> body) throws InvalidSettingException {
        String column = request == null || request.column() == null ? "" : request.column().trim();
        if (!COLUMNS.contains(column)) throw new InvalidSettingException("No such column");
        if (request.shown() == null) throw new InvalidSettingException("A column is shown or not");
        body.set(new ColumnInput(column, request.shown()));
    }
}

